ALTER TABLE public.fuel_card_invoices ADD COLUMN due_on date;
CREATE FUNCTION public.b2b_fuel_invoice_due() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE days integer; BEGIN SELECT t.payment_days INTO days FROM public.fuel_card_accounts a JOIN public.b2b_terms t ON t.client_id=a.client_id AND t.tenant_id=a.tenant_id AND t.country_id=a.country_id WHERE a.id=NEW.account_id AND a.tenant_id=NEW.tenant_id AND a.country_id=NEW.country_id ORDER BY t.effective_at DESC,t.created_at DESC LIMIT 1; NEW.due_on:=NEW.period_end+COALESCE(days,30); RETURN NEW; END $$;
CREATE TRIGGER b2b_fuel_invoice_due BEFORE INSERT ON public.fuel_card_invoices FOR EACH ROW EXECUTE FUNCTION public.b2b_fuel_invoice_due();
CREATE FUNCTION public.b2b_fuel_purchase_terms() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE terms public.b2b_terms%ROWTYPE; customer uuid; BEGIN IF NEW.kind<>'purchase' THEN RETURN NEW; END IF; SELECT client_id INTO customer FROM public.fuel_card_accounts WHERE id=NEW.account_id AND tenant_id=NEW.tenant_id AND country_id=NEW.country_id; SELECT * INTO terms FROM public.b2b_terms WHERE client_id=customer AND tenant_id=NEW.tenant_id AND country_id=NEW.country_id ORDER BY effective_at DESC,created_at DESC LIMIT 1; IF terms.id IS NULL THEN RETURN NEW; END IF; IF cardinality(terms.site_ids)>0 AND NOT NEW.station_id=ANY(terms.site_ids) THEN RAISE EXCEPTION 'Station non autorisée par le contrat B2B'; END IF; IF terms.negotiated_prices ? NEW.product_id::text AND (NEW.amount/NULLIF(NEW.litres,0))<>(terms.negotiated_prices->>NEW.product_id::text)::numeric THEN RAISE EXCEPTION 'Tarif négocié non respecté'; END IF; RETURN NEW; END $$;
CREATE TRIGGER b2b_fuel_purchase_terms BEFORE INSERT ON public.fuel_card_transactions FOR EACH ROW EXECUTE FUNCTION public.b2b_fuel_purchase_terms();
CREATE FUNCTION public.b2b_invoice_due() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE days integer; BEGIN SELECT payment_days INTO days FROM public.b2b_terms WHERE client_id=NEW.client_id AND tenant_id=NEW.tenant_id AND country_id=NEW.country_id ORDER BY effective_at DESC,created_at DESC LIMIT 1; NEW.due_on:=NEW.period_end+COALESCE(days,30); RETURN NEW; END $$;
CREATE TRIGGER b2b_invoice_due BEFORE INSERT ON public.b2b_invoices FOR EACH ROW EXECUTE FUNCTION public.b2b_invoice_due();